import re

_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-((?:[0-9A-Za-z-]+)(?:\.[0-9A-Za-z-]+)*))?$"
)


def parse_version(s):
    if not isinstance(s, str):
        raise ValueError

    m = _VERSION_RE.match(s)
    if not m:
        raise ValueError

    major, minor, patch, pre = m.groups()
    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))

    if pre is None:
        prerelease = None
    else:
        identifiers = []
        for part in pre.split("."):
            if not part:
                raise ValueError
            if all("0" <= ch <= "9" for ch in part):
                if len(part) > 1 and part[0] == "0":
                    raise ValueError
                identifiers.append((0, int(part)))
            else:
                identifiers.append((1, part))
        prerelease = tuple(identifiers)

    return (major, minor, patch, prerelease)


def compare_versions(a, b):
    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1

    ap, bp = a[3], b[3]
    if ap is None:
        if bp is None:
            return 0
        return 1
    if bp is None:
        return -1

    if ap < bp:
        return -1
    if ap > bp:
        return 1
    return 0


def parse_comparator(c):
    if not isinstance(c, str) or not c:
        raise ValueError

    operators = (">=", "<=", ">", "<", "=", "^", "~")
    op = ""
    for candidate in operators:
        if c.startswith(candidate):
            op = candidate
            break

    version_str = c[len(op):]
    version = parse_version(version_str)
    return op, version


def parse_range(rng):
    if not isinstance(rng, str):
        raise ValueError

    raw_sets = rng.split("||")
    if not raw_sets:
        raise ValueError

    parsed_sets = []
    for raw_set in raw_sets:
        comparator_strings = raw_set.split()
        if not comparator_strings:
            raise ValueError

        parsed_set = []
        for comparator_string in comparator_strings:
            parsed_set.append(parse_comparator(comparator_string))
        parsed_sets.append(parsed_set)

    return parsed_sets


def caret_upper_bound(v):
    major, minor, patch, _ = v
    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def tilde_upper_bound(v):
    major, minor, patch, _ = v
    return (major, minor + 1, 0, None)


def comparator_satisfied(version, comparator):
    op, named = comparator

    if op == "":
        return compare_versions(version, named) == 0
    if op == "=":
        return compare_versions(version, named) == 0
    if op == ">":
        return compare_versions(version, named) > 0
    if op == ">=":
        return compare_versions(version, named) >= 0
    if op == "<":
        return compare_versions(version, named) < 0
    if op == "<=":
        return compare_versions(version, named) <= 0
    if op == "^":
        return (
            compare_versions(version, named) >= 0
            and compare_versions(version, caret_upper_bound(named)) < 0
        )
    if op == "~":
        return (
            compare_versions(version, named) >= 0
            and compare_versions(version, tilde_upper_bound(named)) < 0
        )

    raise ValueError


def satisfies(version, rng):
    """Return True if `version` satisfies the range `rng`, else False.

    Versions are "MAJOR.MINOR.PATCH" optionally followed by "-PRERELEASE", where PRERELEASE is one or more
    dot-separated identifiers made of [0-9A-Za-z-]. MAJOR, MINOR, PATCH and purely numeric prerelease identifiers
    are non-negative integers without leading zeros ("0" is fine). Build metadata ("+...") is not allowed.
    An invalid version or range raises ValueError; the WHOLE range is validated even if an earlier part matches.

    Precedence (SemVer 2.0.0): compare MAJOR, MINOR, PATCH numerically. A version with a prerelease is lower than
    the same version without one. Prerelease identifiers are compared left to right: numeric ones numerically,
    alphanumeric ones in ASCII order, numeric always lower than alphanumeric, and if all shared identifiers are
    equal the version with fewer identifiers is lower.

    Range grammar: one or more comparator sets separated by "||" (whitespace around "||" is ignored). The range
    is satisfied if ANY set is satisfied. A set is one or more comparators separated by whitespace; it is
    satisfied if ALL its comparators are. An empty set (e.g. "1.0.0 ||") is invalid. Comparators, with no
    whitespace between operator and version:
        "V" or "=V"   equal to V
        ">V" ">=V" "<V" "<=V"
        "^V"          >=V and below the next "significant" version: < (MAJOR+1).0.0 if MAJOR > 0,
                      else < 0.(MINOR+1).0 if MINOR > 0, else < 0.0.(PATCH+1)
        "~V"          >=V and < MAJOR.(MINOR+1).0

    Prerelease rule: a version that HAS a prerelease satisfies a set only if, in addition, some comparator in that
    set names a version with the same MAJOR.MINOR.PATCH that also has a prerelease (for ^V and ~V the named
    version is V). Versions without a prerelease are not affected by this rule.
    """
    parsed_version = parse_version(version)
    parsed_sets = parse_range(rng)

    version_has_prerelease = parsed_version[3] is not None

    for comparator_set in parsed_sets:
        if version_has_prerelease:
            prerelease_anchor = False
            for _, named in comparator_set:
                if (
                    named[3] is not None
                    and named[0] == parsed_version[0]
                    and named[1] == parsed_version[1]
                    and named[2] == parsed_version[2]
                ):
                    prerelease_anchor = True
                    break
            if not prerelease_anchor:
                continue

        if all(comparator_satisfied(parsed_version, comparator) for comparator in comparator_set):
            return True

    return False
