from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError

    ranges = [
        (0, 59),
        (0, 23),
        (1, 31),
        (1, 12),
        (0, 7),
    ]

    def parse_field(field, lo, hi, dow=False):
        if field == "*":
            values = set(range(lo, hi + 1))
            if dow:
                values = {0 if v == 7 else v for v in values}
            return values, False

        values = set()
        for item in field.split(","):
            if not item:
                raise ValueError

            if "/" in item:
                base, step_str = item.split("/", 1)
                if "/" in step_str:
                    raise ValueError
                if not step_str.isdigit():
                    raise ValueError
                step = int(step_str)
                if step < 1:
                    raise ValueError
            else:
                base = item
                step = 1

            if not base:
                raise ValueError

            if base == "*":
                start, end = lo, hi
            elif "-" in base:
                if base.count("-") != 1:
                    raise ValueError
                a_str, b_str = base.split("-", 1)
                if not a_str.isdigit() or not b_str.isdigit():
                    raise ValueError
                start, end = int(a_str), int(b_str)
                if start < lo or end > hi:
                    raise ValueError
                if start > end:
                    raise ValueError
            else:
                if not base.isdigit():
                    raise ValueError
                start = end = int(base)
                if start < lo or end > hi:
                    raise ValueError

            for v in range(start, end + 1, step):
                if dow and v == 7:
                    v = 0
                values.add(v)

        if not values:
            raise ValueError

        return values, True

    minutes, _ = parse_field(fields[0], *ranges[0])
    hours, _ = parse_field(fields[1], *ranges[1])
    doms, dom_restricted = parse_field(fields[2], *ranges[2])
    months, _ = parse_field(fields[3], *ranges[3])
    dows, dow_restricted = parse_field(fields[4], *ranges[4], dow=True)

    sorted_hours = sorted(hours)
    sorted_minutes = sorted(minutes)

    def cron_dow(dt):
        # Python: Mon=0 ... Sun=6
        # Cron:  Sun=0, Mon=1 ... Sat=6
        return 0 if dt.weekday() == 6 else dt.weekday() + 1

    def day_matches(dt):
        if dt.month not in months:
            return False

        dom_ok = dt.day in doms
        dow_ok = cron_dow(dt) in dows

        if dom_restricted and dow_restricted:
            return dom_ok or dow_ok
        return dom_ok and dow_ok

    current = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    while current <= limit:
        if day_matches(current):
            same_day = current.date() == current.date()
            if same_day:
                for h in sorted_hours:
                    if h < current.hour:
                        continue
                    if h == current.hour:
                        for m in sorted_minutes:
                            if m >= current.minute:
                                candidate = current.replace(hour=h, minute=m, second=0, microsecond=0)
