class PatchError(ValueError):
    pass


def apply_patch(doc, ops):
    """Apply a JSON Patch (RFC 6902 subset) to `doc` and return the resulting NEW document.

    `doc` and `ops` must never be modified, and the result must share no mutable object (dict/list) with either.
    The patch is all-or-nothing: on any error, raise PatchError.

    `ops` is a list of dicts. Each has "op" (one of add, remove, replace, move, copy, test) and "path";
    add/replace/test also need "value" (which may be None); move/copy also need "from". Missing keys are errors.

    Paths are JSON Pointers: "" is the whole document; otherwise "/" followed by "/"-separated tokens in which
    "~1" stands for "/" and "~0" for "~" ("~01" is the key "~1"). A "~" not followed by 0 or 1 is an error.
    A token addressing a list must be a base-10 index without leading zeros ("0" is fine). "-" means "past the
    end of the list" and is only allowed as the final token of an add (or of the target of move/copy).

    add:     object -> set the member (replacing any existing value); list -> insert BEFORE the index
             (index == len appends, index > len is an error). Adding at "" replaces the whole document.
             The parent container must exist.
    remove:  the target must exist. Removing "" is an error.
    replace: the target must exist. Replacing "" replaces the whole document.
    move:    remove the value at "from", then add it at "path". It is an error if "path" lies strictly inside
             "from" (a proper descendant). from == path is a no-op, but "from" must still exist.
    copy:    add a deep copy of the value at "from" at "path".
    test:    the target must exist and equal "value". Equality is JSON equality: numbers by value (1 == 1.0),
             booleans are never equal to numbers, objects by keys and values, lists elementwise.
    """
    import copy

    def parse_pointer(path):
        if not isinstance(path, str):
            raise PatchError
        if path == "":
            return []
        if not path.startswith("/"):
            raise PatchError

        raw_tokens = path.split("/")[1:]
        tokens = []
        for raw in raw_tokens:
            out = []
            i = 0
            while i < len(raw):
                c = raw[i]
                if c == "~":
                    if i + 1 >= len(raw) or raw[i + 1] not in "01":
                        raise PatchError
                    if raw[i + 1] == "0":
                        out.append("~")
                    else:
                        out.append("/")
                    i += 2
                else:
                    out.append(c)
                    i += 1
            tokens.append("".join(out))
        return tokens

    def parse_index(token):
        if not token:
            raise PatchError
        for c in token:
            if c < "0" or c > "9":
                raise PatchError
        if len(token) > 1 and token[0] == "0":
            raise PatchError
        return int(token)

    def json_equal(a, b):
        a_bool = isinstance(a, bool)
        b_bool = isinstance(b, bool)
        if a_bool or b_bool:
            return a_bool and b_bool and a == b

        a_num = isinstance(a, (int, float))
        b_num = isinstance(b, (int, float))
        if a_num or b_num:
            return a_num and b_num and a == b

        if isinstance(a, dict) and isinstance(b, dict):
            if set(a.keys()) != set(b.keys()):
                return False
            for k in a:
                if not json_equal(a[k], b[k]):
                    return False
            return True

        if isinstance(a, list) and isinstance(b, list):
            if len(a) != len(b):
                return False
            for x, y in zip(a, b):
                if not json_equal(x, y):
                    return False
            return True

        return type(a) is type(b) and a == b

    def get_existing(root, tokens):
        cur = root
        for token in tokens:
            if isinstance(cur, dict):
                if token not in cur:
                    raise PatchError
                cur = cur[token]
            elif isinstance(cur, list):
                if token == "-":
                    raise PatchError
                idx = parse_index(token)
                if idx < 0 or idx >= len(cur):
                    raise PatchError
                cur = cur[idx]
            else:
                raise PatchError
        return cur

    def exists(root, tokens):
        try:
            get_existing(root, tokens)
            return True
        except PatchError:
            return False

    def remove_at(root, tokens):
        if not tokens:
            raise PatchError

        parent = get_existing(root, tokens[:-1])
        token = tokens[-1]

        if isinstance(parent, dict):
            if token not in parent:
                raise PatchError
            del parent[token]
        elif isinstance(parent, list):
            if token == "-":
                raise PatchError
            idx = parse_index(token)
            if idx < 0 or idx >= len(parent):
                raise PatchError
            del parent[idx]
        else:
            raise PatchError

    def replace_at(root, tokens, value):
        if not tokens:
            return copy.deepcopy(value)

        parent = get_existing(root, tokens[:-1])
        token = tokens[-1]

        if isinstance(parent, dict):
            if token not in parent:
                raise PatchError
            parent[token] = copy.deepcopy(value)
        elif isinstance(parent, list):
            if token == "-":
                raise PatchError
            idx = parse_index(token)
            if idx < 0 or idx >= len(parent):
                raise PatchError
            parent[idx] = copy.deepcopy(value)
        else:
            raise PatchError

        return root

    def add_at(root, tokens, value):
        if not tokens:
            return copy.deepcopy(value)

        parent = get_existing(root, tokens[:-1])
        token = tokens[-1]

        if isinstance(parent, dict):
            parent[token] = copy.deepcopy(value)
        elif isinstance(parent, list):
            if token == "-":
                parent.append(copy.deepcopy(value))
            else:
                idx = parse_index(token)
                if idx < 0 or idx > len(parent):
                    raise PatchError
                parent.insert(idx, copy.deepcopy(value))
        else:
            raise PatchError

