class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = cycle


def build_order(deps):
    """`deps` maps each target (str) to an iterable of targets it depends on (duplicates allowed). Targets that only
    appear as dependencies are leaves. Return a list of ALL targets in which every target comes after all of its
    dependencies. Whenever several targets are ready, the lexicographically smallest is placed first, so the
    order is unique.

    If the graph has a cycle (including a target depending on itself), raise CycleError(cycle) where `cycle`
    lists the targets on the cycle: it starts with the lexicographically smallest target ON the cycle, each element
    depends on the next one, and it ends by repeating the first element (e.g. ["a", "b", "a"], or ["x", "x"]).
    Targets that merely lead into a cycle are not part of it. Inputs with cycles contain exactly one cycle.
    `deps` must not be modified.
    """
    unique_deps = {}
    all_nodes = set()

    for node, iterable in deps.items():
        unique_deps[node] = set(iterable)
        all_nodes.add(node)
        all_nodes.update(unique_deps[node])

    for node in all_nodes:
        unique_deps.setdefault(node, set())

    dependents = {node: set() for node in all_nodes}
    indegree = {node: 0 for node in all_nodes}

    for node, dependencies in unique_deps.items():
        for dependency in dependencies:
            dependents[dependency].add(node)
            indegree[node] += 1

    import heapq

    ready = [node for node, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)

    order = []

    while ready:
        node = heapq.heappop(ready)
        order.append(node)

        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) == len(all_nodes):
        return order

    remaining = {node for node in all_nodes if node not in set(order)}

    # Remove nodes that merely lead into the cycle, leaving only cycle nodes.
    while True:
        remaining_indegree = {node: 0 for node in remaining}
        for node in remaining:
            for dependency in unique_deps[node]:
                if dependency in remaining:
                    remaining_indegree[dependency] += 1

        removable = {node for node, degree in remaining_indegree.items() if degree == 0}
        if not removable:
            break
        remaining -= removable

    cycle_nodes = remaining
    start = min(cycle_nodes)

    cycle = [start]
    current = start

    while True:
        next_nodes = [dependency for dependency in unique_deps[current] if dependency in cycle_nodes]
        if not next_nodes:
            break

        # Prefer a deterministic choice; with exactly one cycle this is sufficient.
        nxt = min(next_nodes)
        cycle.append(nxt)

        if nxt == start:
            break

        current = nxt

    raise CycleError(cycle)
