    def parse_pattern(pattern):
        segments = []
        current = []
        i = 0
        n = len(pattern)

        while i < n:
            ch = pattern[i]

            if ch == "\\":
                if i + 1 >= n:
                    raise ValueError("trailing lone backslash")
                current.append(("literal", pattern[i + 1]))
                i += 2
                continue

            if ch == "/" and not any(tok[0] == "set" for tok in current):
                segments.append(current)
                current = []
                i += 1
                continue

            if ch == "?":
                current.append(("?",))
                i += 1
                continue

            if ch == "*":
                if i + 1 < n and pattern[i + 1] == "*":
                    current.append(("*", "*"))
                    i += 2
                else:
                    current.append(("*",))
                    i += 1
                continue

            if ch == "[":
                j = i + 1
                negate = False
                if j < n and pattern[j] == "!":
                    negate = True
                    j += 1

                members = []
                if j < n and pattern[j] == "]":
                    members.append(pattern[j])
                    j += 1

                while j < n:
                    if pattern[j] == "]":
                        break
                    if (
                        j + 2 < n
                        and pattern[j + 1] == "-"
                        and pattern[j + 2] != "]"
                    ):
                        start = pattern[j]
                        end = pattern[j + 2]
                        if start > end:
                            members.append("-")
                            members.append(start)
                            members.append(end)
                        else:
                            members.append((start, end))
                        j += 3
                    else:
                        members.append(pattern[j])
                        j += 1

                if j >= n:
                    raise ValueError("unterminated [")

                current.append(("set", negate, members))
                i = j + 1
                continue

