        return segments

    def segment_matches(tokens, text):
        m = len(tokens)
        n = len(text)
        active = {0}

        for pos in range(n + 1):
            if pos == n:
                if m in active:
                    return True

            new_active = set()

            for state in active:
                if state == m:
                    continue

                tok = tokens[state]

                if tok[0] == "literal":
                    if pos < n and text[pos] == tok[1]:
