        return False

    def is_double_star_segment(tokens):
        return len(tokens) == 2 and tokens[0] == ("*",) and tokens[1] == ("*",)

    def split_path_segments(path):
        return path.split("/")

    def match_segments(pattern_segments, path_segments):
        p = len(pattern_segments)
        s = len(path_segments)

        # dp[i][j] means pattern segments i: match path segments j:
        dp = [[False] * (s + 1) for _ in range(p + 1)]
