    y_num = y.isdigit()

    if x_num and y_num:
        xi = int(x)
        yi = int(y)
        if xi != yi:
            return -1 if xi < yi else 1
        return 0

    if x_num:
        return -1
    if y_num:
        return 1

    if x < y:
        return -1
    if x > y:
        return 1
    return 0


def _compare_comparator(v, op, named):
    c = _compare_versions(v, named)

    if op == "=":
        return c == 0
    if op == ">":
        return c > 0
    if op == ">=":
        return c >= 0
    if op == "<":
        return c < 0
    if op == "<=":
        return c <= 0

    if op == "^":
        if c < 0:
            return False
        major, minor, patch, _ = named
        if major > 0:
            upper = (major + 1, 0, 0, ())
        elif minor > 0:
            upper = (0, minor + 1, 0, ())
        else:
            upper = (0, 0, patch + 1, ())
        return _compare_versions(v, upper) < 0

    if op == "~":
