def _parse_comparator(c):
    if not c:
        raise ValueError("invalid comparator")

    if c.startswith(">="):
        op = ">="
        ver = c[2:]
    elif c.startswith("<="):
        op = "<="
        ver = c[2:]
    elif c.startswith(">"):
        op = ">"
        ver = c[1:]
    elif c.startswith("<"):
        op = "<"
        ver = c[1:]
    elif c.startswith("="):
        op = "="
        ver = c[1:]
    elif c.startswith("^"):
        op = "^"
        ver = c[1:]
    elif c.startswith("~"):
        op = "~"
        ver = c[1:]
    else:
        op = "="
        ver = c

    if not ver:
        raise ValueError("invalid comparator")

    return op, _parse_version(ver)


def _parse_range(rng):
    parts = rng.split("||")
    sets = []

    for part in parts:
        part = part.strip()
        if not part:
            raise ValueError("invalid range")

        comparators = part.split()
        if not comparators:
            raise ValueError("invalid range")

        sets.append([_parse_comparator(c) for c in comparators])

    return sets
