def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError

    ranges = [
        (0, 59),
        (0, 23),
        (1, 31),
        (1, 12),
        (0, 7),
    ]

    parsed = []
    unrestricted = []

    for field, (lo, hi) in zip(fields, ranges):
        if field == "":
            raise ValueError

        values = set()

        for item in field.split(","):
            if item == "":
                raise ValueError

            if "/" in item:
                base, step_part = item.split("/", 1)
                if "/" in step_part:
                    raise ValueError
                if not step_part.isdigit():
                    raise ValueError
                step = int(step_part)
                if step < 1:
                    raise ValueError
            else:
                base = item
                step = 1

            if base == "*":
                start = lo
                end = hi
            elif "-" in base:
                if base.count("-") != 1:
                    raise ValueError
                a_s, b_s = base.split("-", 1)
                if not a_s.isdigit() or not b_s.isdigit():
                    raise ValueError
                a = int(a_s)
                b = int(b_s)
                if a < lo or a > hi or b < lo or b > hi:
                    raise ValueError
                if a > b:
                    raise ValueError
                start = a
                end = b
            else:
                if not base.isdigit():
                    raise ValueError
                n = int(base)
                if n < lo or n > hi:
                    raise ValueError
                start = n
                end = n if step == 1 else hi

            values.update(range(start, end + 1, step))

        parsed.append(values)
        unrestricted.append(field == "*")

    minutes, hours, doms, months, dows = parsed
    dom_unrestricted, dow_unrestricted = unrestricted[2], unrestricted[4]

    normalized_dows = set()
    for d in dows:
        if d == 0 or d == 7:
            normalized_dows.add(6)
        else:
            normalized_dows.add(d - 1)

    def day_matches(dt):
        dom_ok = dt.day in doms
        dow_ok = dt.weekday() in normalized_dows

        if dom_unrestricted and dow_unrestricted:
            return True
        if dom_unrestricted:
            return dow_ok
        if dow_unrestricted:
            return dom_ok
        return dom_ok or dow_ok

    start = (after + timedelta(minutes=1)).replace(second=0, microsecond=0)
    limit = after + timedelta(days=3000)

    if start > limit:
        raise ValueError

    current = start
    while current <= limit:
        if current.month not in months:
            if current.month == 12:
                current = datetime(current.year + 1, 1, 1)
            else:
                current = datetime(current.year, current.month + 1, 1)
            continue

        if not day_matches(current):
            current = current + timedelta(days=1)
            current = current.replace(hour=0, minute=0, second=0, microsecond=0)
            continue

        if current.hour not in hours:
            current = current + timedelta(hours=1)
            current = current.replace(minute=0, second=0, microsecond=0)
            continue

        if current.minute not in minutes:
            current = current + timedelta(minutes=1)
            current = current.replace(second=0, microsecond=0)
            continue

        return current

    raise ValueError
