            i = 0
            while i < len(raw):
                c = raw[i]
                if c == "~":
                    if i + 1 >= len(raw):
                        raise PatchError
                    nxt = raw[i + 1]
                    if nxt == "0":
                        token_chars.append("~")
                        i += 2
                    elif nxt == "1":
                        token_chars.append("/")
                        i += 2
