def glob_match(pattern, path):
    r"""Return True if the "/"-separated relative `path` matches `pattern` (case-sensitive, whole path).

    Pattern syntax:
    - `?` matches exactly one character other than "/".
    - `*` matches zero or more characters other than "/".
    - `[...]` matches one character other than "/" that is in the set; `[!...]` one that is NOT in the set.
      The set holds literal characters and ranges `a-z`. A `]` right after `[` or `[!` is a literal member, and a
      `-` first or last in the set is literal. Backslash has no special meaning inside a set.
      An unterminated `[` raises ValueError.
    - `\x` (backslash then any character) matches x literally. A trailing lone backslash raises ValueError.
    - A pattern segment (text between unescaped "/" outside sets) that is exactly `**` matches zero or more whole
      path segments. Elsewhere `**` is just two `*`.
    - Any other character matches itself.
    Matching must stay fast for patterns with many `*` or `**` (no exponential backtracking).
    """
    def parse_pattern(pattern):
        segments = []
        current = []
        exact_double_star = True
        star_count = 0
        other_count = 0

        i = 0
        n = len(pattern)

        def finish_segment():
            nonlocal current, exact_double_star, star_count, other_count
            if exact_double_star and star_count == 2 and other_count == 0:
                segments.append("**")
            else:
                segments.append(current)
            current = []
            exact_double_star = True
            star_count = 0
            other_count = 0

        while i < n:
            ch = pattern[i]

            if ch == "\\":
                if i + 1 >= n:
                    raise ValueError("trailing lone backslash")
                current.append(("literal", pattern[i + 1]))
                exact_double_star = False
                other_count += 1
                i += 2
                continue

            if ch == "/" and not any(tok[0] == "set_open" for tok in current):
                finish_segment()
                i += 1
                continue

            if ch == "[":
                j = i + 1
                negated = False
                if j < n and pattern[j] == "!":
                    negated = True
                    j += 1

                members = []
                if j < n and pattern[j] == "]":
                    members.append("]")
                    j += 1

                while j < n:
                    if pattern[j] == "]":
                        break

                    c = pattern[j]
                    if (
                        j + 2 < n
                        and pattern[j + 1] == "-"
                        and pattern[j + 2] != "]"
                    ):
                        start = c
                        end = pattern[j + 2]
                        if start <= end:
                            members.append((start, end))
                        else:
                            members.append(c)
                            members.append("-")
                            members.append(end)
                        j += 3
                    else:
                        members.append(c)
                        j += 1

                if j >= n:
                    raise ValueError("unterminated [")

                current.append(("class", negated, members))
                exact_double_star = False
                other_count += 1
                i = j + 1
                continue

            if ch == "*":
                current.append(("star",))
                star_count += 1
                i += 1
                continue

            if ch == "?":
                current.append(("any",))
                exact_double_star = False
                other_count += 1
                i += 1
                continue

            current.append(("literal", ch))
            exact_double_star = False
            other_count += 1
            i += 1

        finish_segment()
        return segments

    def segment_match(tokens, text):
        compressed = []
        for tok in tokens:
            if tok[0] == "star":
                if compressed and compressed[-1][0] == "star":
                    continue
            compressed.append(tok)

        m = len(compressed)
        if m == 0:
            return text == ""

        star_mask = 0
        for idx, tok in enumerate(compressed):
            if tok[0] == "star":
                star_mask |= 1 << idx

        def closure(states):
            return states | ((states & star_mask) << 1)

        active = closure(1)
        end_bit = 1 << m

        for ch in text:
            match_mask = 0
            for idx, tok in enumerate(compressed):
                kind = tok[0]
                if kind == "literal":
                    if tok[1] == ch:
                        match_mask |= 1 << idx
                elif kind == "any":
                    if ch != "/":
                        match_mask |= 1 << idx
                elif kind == "class":
                    negated = tok[1]
                    members = tok[2]
                    in_set = False
                    for member in members:
                        if isinstance(member, tuple):
                            if member[0] <= ch <= member[1]:
                                in_set = True
                                break
                        elif member == ch:
                            in_set = True
                            break

                    if ch != "/" and (in_set != negated):
                        match_mask |= 1 << idx

            active = closure(((active & match_mask) << 1) | (active & star_mask))
            if active == 0:
                return False

        return (active & end_bit) != 0

    def split_path(path):
        if path == "":
            return [""]
        return path.split("/")

    def split_pattern_segments(pattern):
        return parse_pattern(pattern)

    pattern_segments = split_pattern_segments(pattern)
    path_segments = split_path(path)

    reachable = {0}

    def advance_through_double_star(indices):
        out = set(indices)
        changed = True
        while changed:
            changed = False
            for idx in list(out):
                if idx < len(pattern_segments) and pattern_segments[idx] == "**":
                    nxt = idx + 1
                    if nxt not in out:
                        out.add(nxt)
                        changed = True
        return out

    reachable = advance_through_double_star(reachable)

    for segment in path_segments:
        nxt = set()
        for idx in reachable:
            if idx >= len(pattern_segments):
                continue

            pat_seg = pattern_segments[idx]
            if pat_seg == "**":
                nxt.add(idx)
            elif segment_match(pat_seg, segment):
                nxt.add(idx + 1)

        reachable = advance_through_double_star(nxt)
        if not reachable:
            return False

    return len(pattern_segments) in reachable
