from events import parse_event
from decimal import Decimal

_CENTS = Decimal("0.01")


def _quantize(value):
    return value.quantize(_CENTS)


class Ledger:
    """In-memory account ledger.

    - balance(acct) returns a decimal.Decimal with exactly two decimal places; unknown accounts have Decimal("0.00").
    - apply(raw) returns True when the event is applied, or False when an event with the same id was already APPLIED
      (it is then ignored).
    - Invalid events (see events.parse_event) and events that would make any balance negative raise ValueError,
      change nothing, and are not remembered: a later event with the same id is processed normally.
    - withdraw and transfer may bring a balance down to exactly zero.
    - A transfer moves the amount from `account` to `target` atomically.
    """

    def __init__(self):
        self._bal = {}
        self._seen = set()

    def balance(self, acct):
        return _quantize(self._bal.get(acct, Decimal("0.00")))

    def apply(self, raw):
        if isinstance(raw, dict) and raw.get("id") in self._seen:
            return False

        ev = parse_event(raw)

        if ev.id in self._seen:
            return False

        if ev.kind == "deposit":
            self._bal[ev.account] = self._credit(ev.account, ev.amount)
        elif ev.kind == "withdraw":
            self._bal[ev.account] = self._debit(ev.account, ev.amount)
        else:
            new_source = self._debit(ev.account, ev.amount)
            new_target = self._credit(ev.target, ev.amount)
            self._bal[ev.account] = new_source
            self._bal[ev.target] = new_target

        self._seen.add(ev.id)
        return True

    def _credit(self, acct, amount):
        current = self._bal.get(acct, Decimal("0.00"))
        return _quantize(current + amount)

    def _debit(self, acct, amount):
        current = self._bal.get(acct, Decimal("0.00"))
        new_balance = _quantize(current - amount)
        if new_balance < 0:
            raise ValueError("insufficient funds")
        return new_balance
